head.b:skin:
/* ==============================
TEMPLATE NAME: KEADILAN.CO.ID
AUTHOR: Asep Maulana Hasanudin
DESIGN: http://www.keadilan.co.id
================================ */
/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="$(main.color)" value="#16a085"/>
<Variable name="followByEmail" description="Follow By Email Text" type="string" default="Get all latest content delivered straight to your inbox." value="Get all latest content delivered straight to your inbox."/>

<Group description="Theme Colors" selector="body">
 <Variable name="main.color" description="Theme Color" type="color" default="#bb1a73" value="#19b496"/>
  <Variable name="main.dark.color" description="Dark Color" type="color" default="#202020" value="#000000"/>
  <Variable name="title.color" description="Title Color" type="color" default="#222222" value="#000000"/>
  <Variable name="title.hover" description="Title Color on Hover" type="color" default="#555555" value="#000000"/>
  <Variable name="footer.color" description="Footer Color" type="color" default="#ffffff" value="#ffffff"/>
</Group>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body Background Color" hideEditor="true" type="color" default="$(footer.color)"  value="#16a085"/>
  <Variable name="body.background" description="Background" hideEditor="true" type="background" color="$(body.background.color)" default="$(color) url() repeat fixed top left" value="#ffffff url() repeat fixed top left"/>
<Variable name="body.font" description="Text Font" type="font" default="17px -apple-system,BlinkMacSystemFont,segoe ui,helvetica neue,Arial,noto sans,sans-serif,apple color emoji,segoe ui emoji,segoe ui symbol,noto color emoji" value="normal normal 18px Arial, Tahoma, Helvetica, FreeSans, sans-serif"/>
  <Variable name="body.text.color" description="Text Color" type="color" default="#444444"  value="#000000"/>
  <Variable name="body.link.color" description="Link Color" type="color" default="$(main.color)"  value="#16a085"/>
</Group>

<!-- Extra Variables -->
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="$(body.font)"  value="17px -apple-system,BlinkMacSystemFont,segoe ui,helvetica neue,Arial,noto sans,sans-serif,apple color emoji,segoe ui emoji,segoe ui symbol,noto color emoji"/>
<Variable name="posts.background.color" description="Post background color" hideEditor="true" type="color" default="$(footer.color)"  value="#ffffff"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="$(body.font)"  value="17px -apple-system,BlinkMacSystemFont,segoe ui,helvetica neue,Arial,noto sans,sans-serif,apple color emoji,segoe ui emoji,segoe ui symbol,noto color emoji"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="#333333"  value="#111111"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="#656565"  value="#616161"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)"  value="#bb1a73"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="$(main.color)"  value="#bb1a73"/>
*/
/*-- Reset CSS --*/
.owl-theme .owl-dots,
.owl-theme .owl-nav {
    text-align: center;
    -webkit-tap-highlight-color: transparent
}

.owl-theme .owl-nav {
    margin-top: 10px
}

.owl-theme .owl-nav [class*=owl-] {
    color: $(footer.color);
    font-size: 14px;
    margin: 5px;
    padding: 4px 7px;
    background: #D6D6D6;
    display: inline-block;
    cursor: pointer;
    border-radius: 3px
}

.owl-theme .owl-nav [class*=owl-]:hover {
    background: #869791;
    color: $(footer.color);
    text-decoration: none
}

.owl-theme .owl-nav .disabled {
    opacity: .5;
    cursor: default
}

.owl-theme .owl-nav.disabled+.owl-dots {
    margin-top: 10px
}

.owl-theme .owl-dots .owl-dot {
    display: inline-block;
    zoom: 1
}

.owl-theme .owl-dots .owl-dot span {
    width: 10px;
    height: 10px;
    margin: 5px 7px;
    background: #D6D6D6;
    display: block;
    -webkit-backface-visibility: visible;
    transition: opacity .2s ease;
    border-radius: 30px
}

.owl-theme .owl-dots .owl-dot.active span,
.owl-theme .owl-dots .owl-dot:hover span {
    background: #869791
}

a,
abbr,
acronym,
address,
applet,
b,
big,
blockquote,
body,
caption,
center,
cite,
code,
dd,
del,
dfn,
div,
dl,
dt,
em,
fieldset,
font,
form,
h1,
h2,
h3,
h4,
h5,
h6,
html,
i,
iframe,
img,
ins,
kbd,
label,
legend,
li,
object,
p,
pre,
q,
s,
samp,
small,
span,
strike,
strong,
sub,
sup,
table,
tbody,
td,
tfoot,
th,
thead,
tr,
tt,
u,
ul,
var {
    padding: 0;
    border: 0;
    outline: 0;
    vertical-align: baseline;
    background: 0
}

ins {
    text-decoration: underline
}

del {
    text-decoration: line-through
}

a,
a:visited,
abbr,
body {
    text-decoration: none
}

blockquote {
    font-style: italic;
    color: #555
}

caption,
th {
    text-align: center
}

.blog-post,
body {
    word-wrap: break-word
}

.owl-carousel,
.owl-carousel .owl-item {
    -webkit-tap-highlight-color: transparent
}

img {
    border: 0;
    position: relative;
    height: auto
}

.section,
.widget,
.widget ul {
    margin: 0;
    padding: 0
}

a {
    color: $(title.hover)
}

a:hover {
    color: $(main.color)
}

:focus {
    outline: 0
}

a img,
button {
    border: 0
}

brc {
    color: #bdbdbd
}

.CSS_LIGHTBOX {
    z-index: 999999 !important
}

.separator a {
    clear: none !important;
    float: none !important;
    margin-left: 0 !important;
    margin-right: 0 !important
}

*,
:after,
:before {
    -webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    box-sizing: border-box;
    margin: 0;
    padding: 0
}

*,
:after,
:before {
    outline: 0;
    transition: all 0s ease;
    -webkit-transition: all 0s ease;
    -moz-transition: all 0s ease;
    -o-transition: all 0s ease
}

#sidebar-wrapper {
    -webkit-box-sizing: border-box;
    min-width: 0
}

h1 {
    font-size: 1.6rem
}

h2 {
    font-size: 1.4rem
}

h3 {
    font-size: 1.2rem
}

h4 {
    font-size: 1rem
}

h5 {
    font-size: .9rem
}

h6 {
    font-size: .7rem
}

h1,
h2,
h3,
h4,
h5,
h6 {
    font: $(body.font);
    text-rendering: optimizeSpeed;
    font-weight: 700;
    letter-spacing: -.02em;
    text-rendering: optimizelegibility
}

body,
p {
    font: $(body.font)
}

body {
    background: $(body.background);
    color: $(body.text.color);
    margin: 0;
    padding: 0;
    line-height: 1.8rem
}

.top-menu,
.top-wrapper {
    justify-content: flex-end;
    display: flex;
    -webkit-flex-flow: row wrap;
    -ms-flex-flow: row wrap;
    flex-flow: row wrap;
    -webkit-align-items: center;
    -ms-flex-align: center;
    align-items: center
}
.header-box .widget-title{display:none}
.top-menu {
    margin-left: 15px
}

.top-menu ul li a i {
    font-size: 11px;
    vertical-align: middle;
    margin-right: 5px
}

.top-menu ul li {
    display: inline-block;
    list-style: none;
    margin: 0 0 0 10px
}

.top-menu ul li a {
    color: #575757;
    font-weight: 700;
    line-height: 50px;
    font-size: 14px
}

.container {
    max-width: 1170px;
    margin: 0 auto;
    padding: 0 15px
}

#outer-wrapper {
    max-width: 100%;
    margin: 0 auto
}

#main-wrapper {
    -webkit-box-flex: 1;
    -ms-flex: 1 1 66.666%;
    flex: 1 1 66.666%;
    max-width: 66.666%;
    min-width: 0
}

#main-wrapper .container {
    max-width: inherit;
    padding: 0
}

#sidebar-wrapper {
    -webkit-box-flex: 1;
    -ms-flex: 1 1 30%;
    flex: 1 1 33.333%;
    max-width: 33.333%;
    padding: 0;
    box-sizing: border-box;
    position: relative
}

#sidebar-wrapper .sidebar,
#sidebar-wrapper.widget {
    position: sticky;
    top: 65px;
    padding-left: 30px
}

.about-author .avatar-container,
.comments .avatar-image-container {
    background-color: rgba(155, 155, 155, .07);
    color: transparent !important
}

.modegrid {
    -ms-flex-order: 2;
    order: 2;
    -webkit-box-flex: 1;
    -ms-flex: 1 1 auto;
    flex: 1 1 auto;
    float: right;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-pack: end;
    -ms-flex-pack: end;
    justify-content: flex-end
}

.gridmode .mediapost,
.header {
    -ms-flex-flow: row wrap;
    -webkit-box-orient: horizontal;
    -webkit-box-direction: normal
}

.modegrid .switch {
    position: relative;
    display: block;
    vertical-align: middle
}

.modegrid .switch input {
    opacity: 0;
    display: none
}

.modegrid .slider {
    position: relative;
    padding: 0;
    cursor: pointer;
    -webkit-transition: .2s;
    font-size: 22px;
    color: $(main.color);
    transition: .2s
}

.modegrid .slider:before {
    content: "\ee90";
    font-family: 'remixicon';
    font-size: 26px;
    font-weight: 900
}

.modegrid input:checked+.slider:before {
    font-size: 23px;
    content: "\ee83";
    font-family: "remixicon";
}

.linkall {
    border-radius: 4px !important;
    padding: 3px 10px !important;
    line-height: 19px !important
}

.gridmode .mediapost {
    width: 33.333%;
    padding: 0 10px;
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    flex-flow: row wrap;
    border-bottom: 0;
    margin-bottom: 20px
}

.gridmode .mediapost .rcimg {
    margin-right: 0;
    margin-bottom: 10px;
    width: 100%
}

.gridmode .mediapost .post-info {
    position: relative;
    flex: auto;
    padding: 0;
    width: calc(100%)
}

#jt_header,
.header-logo,
.header-wrapper {
    width: 100%;
    position: relative
}

.gridmode .mediapost .post-info .post-snippet {
    position: absolute;
    text-indent: -9999999px
}

.post-title a {
    display: block
}

#jt_header {
    padding: 10px 0;
    display: flex;
    height: 70px;
    margin: 0 auto;
    justify-content: space-between;
    align-items: center
}

#jt_header .jetbtn,
.menu-sticky .jetbtn,
.menu-sticky .type-dark {
    display: none
}

.menu-sticky.sticky .jetbtn,
.menu-sticky.sticky .type-dark {
    display: block
}

.header-wrapper {
    padding: 0;
    background: $(posts.background.color);
    box-shadow: 0 4px 11px 1px rgb(0 0 0 / 16%);
    margin-bottom: 30px
}

.header-logo {
    max-width: 280px;
    padding-top: 10px;
    height: auto;
    margin: 0;
    display: flex;
    align-items: center;
    text-align: center
}

.header-logo .header-image-wrapper {
    display: block;
    height: 33px
}

.header-logo img {
    height: 38px;
    margin: 0;
    width: auto
}

.header-logo h1 {
    color: $(footer.color);
    font-size: 21px;
    line-height: 1.4em;
    font-weight: 700;
    text-transform: uppercase;
    margin: 0
}

.header-logo p {
    font-size: 12px;
    margin: 5px 0 0
}

.header {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    flex-flow: row wrap;
    -webkit-box-flex: 1;
    -ms-flex: 1 1 70%;
    flex: 1 1 70%;
    max-width: 70%;
    min-width: 0;
    -webkit-box-align: center;
    -ms-flex-align: center;
    align-items: center
}

.menu-wrapper .menu {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-orient: horizontal;
    -webkit-box-direction: normal;
    -ms-flex-flow: row wrap;
    flex-flow: row wrap;
    -webkit-box-align: center;
    -ms-flex-align: center;
    align-items: center;
    -webkit-box-pack: start;
    -ms-flex-pack: start;
    justify-content: flex-start
}

.menu-social {
    -webkit-box-ordinal-group: 3;
    -ms-flex-order: 2;
    order: 2;
    -webkit-box-flex: 1;
    -ms-flex: 1 1 auto;
    flex: 1 1 auto;
    min-width: 0;
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-pack: end;
    -ms-flex-pack: end;
    justify-content: flex-end
}

.menu-sticky {
    width: 100%;
    top: -115px;
    -webkit-transition: 1s all ease;
    -moz-transition: 1s all ease;
    transition: 1s all ease
}

.menu-sticky.sticky {
    position: fixed;
    top: 0;
    width: 100%;
    background: $(posts.background.color);
    padding: 0;
    z-index: 999;
    box-shadow: 0 4px 11px 1px rgb(0 0 0 / 16%);
    left: 0
}

.menu-sticky.sticky .menu-social .LinkList,
.static_page .titlehome {
    display: none
}

.header-menu {
    position: relative;
    font-size: 15px;
    margin: 0;
    -webkit-box-flex: 1;
    align-items: center;
    display: flex
}

.header-menu .container {
    position: relative;
    margin: 0 auto;
    padding: 0
}

#jt_header #Attribution1,
#jt_header #BlogArchive1,
#jt_header #BlogSearch1,
#jt_header #ReportAbuse1,
#main-menu .widget,
#main-menu .widget>.widget-title,
.menu-social .widget-title,
.menushow,
.mobile-logo,
.mobile-menu,
.mobile-menu .m-sub,
.mobile-social,
.search-mobile {
    display: none
}

#main-menu .show-menu {
    display: block
}

#main-menu ul>li,
#main-menu ul>li>a {
    position: relative;
    display: inline-block;
    margin: 0
}

#main-menu ul>li>a i {
    margin-right: 5px;
    color: $(main.color)
}

#main-menu {
    position: relative;
    z-index: 15
}

#main-menu ul>li {
    padding: 0;
    transition: background .17s
}

#main-menu ul>li>a {
    color: $(title.color);
    display: block;
    position: relative;
    margin: 0;
    font-size: 17px;
    font-weight: 700;
    line-height: 50px;
    letter-spacing: -1px;
    white-space: nowrap;
    padding: 0 10px
}

#main-menu ul>li>a:hover {
    color: $(title.hover)
}

#main-menu ul ul,
#main-menu ul>li>ul>li,
#main-menu ul>li>ul>li a,
.mobile-menu ul li a {
    transition: all .17s ease
}

.mobile-menu ul li a i {
    margin-right: 5px
}

#main-menu ul>li>ul {
    position: absolute;
    left: 0;
    border-radius: .25rem;
    box-shadow: 0 8px 20px rgb(32 54 86 / 20%);
    top: 100%;
    width: 230px;
    background-color: $(posts.background.color);
    z-index: 99999;
    margin: 0;
    padding: 10px;
    visibility: hidden;
    opacity: 0
}

#slotbanner {
    overflow: hidden;
}

#main-menu ul>li>ul>li>ul {
    position: absolute;
    float: left;
    top: 0;
    left: 100%;
    margin: 0
}

#main-menu ul>li>ul>li {
    display: block;
    float: none;
    position: relative
}

#main-menu ul>li>ul>li a {
    display: block;
    font-size: 14px;
    color: $(title.color);
    font-weight: 400;
    line-height: 1.5;
    margin: 0;
    padding: 5px 15px
}

#main-menu ul>li>ul>li a:hover {
    color: $(main.color)
}

#main-menu ul>li>ul>li:last-child a {
    border-bottom: 0
}

#main-menu ul>li.has-sub>a:after {
    content: '\ea4e';
    float: right;
    font-family: 'remixicon';
    font-size: 14px;
    font-weight: 400;
    margin: 2px 0 0 8px
}

#main-menu ul>li>ul>li.has-sub>a:after {
    content: '\ea6e';
    float: right;
    margin: 0
}

#main-menu .mega-menu {
    position: static !important
}

#main-menu .mega-menu>ul {
    width: 100%;
    padding: 20px 10px
}

#main-menu ul>li:hover>ul,
#main-menu ul>li>ul>li:hover>ul {
    visibility: visible;
    opacity: 1
}

.slide-menu-toggle {
    display: block;
    position: absolute;
    line-height: 42px;
    height: 42px;
    width: 42px;
    top: 0;
    left: 0;
    font-family: "remixicon";
    color: $(footer.color);
    font-size: 17px;
    font-weight: 400;
    text-align: left;
    cursor: pointer;
    z-index: 4;
    padding: 0
}

.mobile-menu ul li,
.mobile-menu ul li a {
    font-size: 15px;
    position: relative;
    display: block
}

.slide-menu-toggle:before {
    content: "\f0c9"
}

.alert-del-btn:before,
.nav-active .slide-menu-toggle:before {
    content: "\f00d"
}

.mobile-menu {
    position: relative;
    padding: 0
}

.mobile-menu>ul {
    margin: 0
}

.mobile-menu>ul::-webkit-scrollbar {
    width: 12px;
    height: 12px;
    background-color: #f2f2f2
}

.mobile-menu>ul::-webkit-scrollbar:hover {
    background-color: #ccc
}

.mobile-menu>ul::-webkit-scrollbar-thumb {
    border: 2px solid transparent;
    -webkit-box-shadow: inset 0 0 0 24px rgba(0, 0, 0, .15);
    -moz-box-shadow: inset 0 0 0 24px rgba(0, 0, 0, .15);
    box-shadow: inset 0 0 0 24px rgba(0, 0, 0, .15);
    -webkit-border-radius: 24px;
    -moz-border-radius: 24px;
    border-radius: 24px
}

.mobile-menu>ul::-webkit-scrollbar-thumb:active {
    box-shadow: inset 0 0 0 24px rgba(0, 0, 0, .3);
    -webkit-box-shadow: inset 0 0 0 24px rgba(0, 0, 0, .3);
    -moz-box-shadow: inset 0 0 0 24px rgba(0, 0, 0, .3);
    -webkit-border-radius: 24px;
    -moz-border-radius: 24px;
    border-radius: 24px
}

.mobile-menu .m-sub {
    padding: 0
}

.mobile-menu ul li {
    overflow: hidden;
    float: left;
    width: 100%;
    font-weight: 600;
    line-height: 38px;
    margin: 0;
    padding: 5px;
    border-bottom: 1px solid #eee
}

.mobile-menu>ul>li:first-child {
    border-top: 0
}

.mobile-menu ul li a {
    padding: 0;
    font-weight: 700
}

.post-body p {
    margin-bottom: 20px
}

.author-description a:hover,
.post-body .tableOfContent #tocContent a:hover,
.post-body u,
.queryMessage a.show-more {
    text-decoration: underline
}

.mobile-menu ul li.has-sub .submenu-toggle {
    position: absolute;
    top: 7px;
    right: 3px;
    color: #eee;
    cursor: pointer
}

.mobile-menu ul li.has-sub .submenu-toggle:after {
    content: '\ea6e';
    font-family: 'remixicon';
    font-weight: 900;
    float: right;
    color: $(main.color);
    vertical-align: middle;
    font-size: 15px;
    text-align: center;
    transition: all .17s ease
}

.mobile-menu>ul>li>ul>li,
.mobile-menu>ul>li>ul>li:last-child {
    border-bottom: 0
}

.mobile-menu ul li.has-sub.show>.submenu-toggle:after {
    transform: rotate(90deg)
}

.mobile-menu>ul>li>ul>li a {
    font-size: 13px;
    text-transform: initial;
    font-weight: 400
}

.mobile-menu>ul>li>ul>li>a {
    color: $(title.color);
    opacity: .7;
    padding: 0 0 0 5px
}

.mobile-menu>ul>li>ul>li>ul>li {
    border-color: rgba(255, 255, 255, .02)
}

.mobile-menu>ul>li>ul>li>ul>li>a {
    color: #203656;
    opacity: .7;
    padding: 0 0 0 10px
}

.mobile-menu ul li a:hover,
.mobile-menu ul>li>.submenu-toggle:hover {
    color: $(main.color)
}

.chiller-theme {
    background: 0
}

.overlay {
    position: fixed;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
    display: none
}

.overlay.active {
    z-index: 999;
    background: $(posts.background.color);
    display: block;
    opacity: .6;
    visibility: visible
}

.mobile-social {
    padding: 20px 0;
    clear: both
}

.mobile-social ul.social-counter {
    margin: 0
}

.mobile-logo {
    margin: 30px 0
}

.menuhide {
    display: none;
    font-size: 25px;
    text-align: right;
    cursor: pointer;
    margin-left: 15px
}

@media screen and (max-width:980px) {
    #main-menu,
    .header-social {
        display: none
    }
    .header-menu,
    .menu,
    .search-mobile {
        display: block !important
    }
    .menushow {
        cursor: pointer;
        margin-left: 5px
    }
    .menu-wrapper .header-social,
    .menu-wrapper .mobile-logo,
    .menu-wrapper .mobile-social,
    .menuhide,
    .menushow,
    .mobile-menu,
    .slide-menu-toggle {
        display: block
    }
    .menu {
        width: 300px;
        height: 100vh;
        padding: 0;
        left: -400px;
        z-index: 999999;
        bottom: 0;
        background: $(posts.background.color);
        top: 0;
        position: fixed;
        -webkit-box-shadow: 8px 0 14px -7px rgb(196 196 196);
        -moz-box-shadow: 8px 0 14px -7px rgb(196 196 196);
        box-shadow: 8px 0 14px -7px rgb(196 196 196);
        transition: .5s linear
    }
    .mobile-menu>ul {
        margin: 0;
        padding: 0 20px;
        overflow-y: auto;
        height: 100vh;
        padding-bottom: 10rem
    }
    .menu.active,
    .page-wrapper.toggled {
