.backtop {
    position: fixed;
    opacity: 0;
    visibility: hidden;
    overflow: hidden;
    z-index: 99;
    background: $(main.color);
    color: #444;
    width: 40px;
    height: 40px;
    line-height: 37px;
    right: 25px;
    text-align: center;
    bottom: -25px;
    -webkit-border-radius: 100%;
    -moz-border-radius: 100%;
    border-radius: 100%;
    -webkit-transition: all .5s ease-in-out;
    -moz-transition: all .5s ease-in-out;
    -ms-transition: all .5s ease-in-out;
    -o-transition: all .5s ease-in-out;
    transition: all .5s ease-in-out;
    -webkit-transition-delay: .2s;
    -moz-transition-delay: .2s;
    -ms-transition-delay: .2s;
    -o-transition-delay: .2s;
    transition-delay: .2s
}

.backtop:hover {
    background-color: $(main.color);
    opacity: .8;
    transition: all .2s ease-in-out;
    transition-delay: 0;
    color: $(footer.color)
}

.backtop.show {
    visibility: visible;
    cursor: pointer;
    opacity: 1;
    bottom: 30px
}

.backtop svg {
    width: 25px;
    vertical-align: middle;
    height: auto
}

.titlehome {
    position: relative;
    width: 100%;
    padding: 0;
    display: flex;
    margin: 0 auto 30px;
    padding-bottom: 5px;
    border-bottom: 2px solid $(main.color)
}

.titlehome h3.home-title {
    font-size: 17px;
    position: relative;
    color: $(title.color);
    margin: 0;
    text-transform: uppercase
}

.titlehome h3 span:after {
    border-bottom: 2px solid $(main.color)
}

#blog-pager {
    width: 100%;
    font-size: 15px;
    text-align: center;
    font-weight: 500;
    clear: both;
    box-sizing: border-box;
    padding: 30px 0 0 !important
}

#blog-pager .load-more,
.recent404-wrapper .homepage a {
    display: inline-block;
    border: 0;
    color: $(footer.color);
    background: $(main.color);
    border-radius: 4px;
    float: none;
    padding: 3px 20px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-size: 13px;
    transition: all .2s;
    -moz-transition: all .2s;
    -webkit-transition: all .2s;
    box-sizing: border-box;
    margin: 0
}

#blog-pager #load-link {
    cursor: pointer
}

#blog-pager #load-link:hover {
    background-color: $(main.color);
    color: $(footer.color)
}

#blog-pager .load-more.no-more {
    background-color: rgba(155, 155, 155, .05);
    color: $(main.color)
}

#blog-pager .loading,
#blog-pager .no-more {
    display: none
}

#blog-pager .loading .loader {
    position: relative;
    overflow: hidden;
    display: block;
    margin: 0;
    height: 34px
}

#blog-pager .no-more.show {
    display: inline-block;
    cursor: no-drop
}

#blog-pager .loading .loader:after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 28px;
    height: 28px;
    margin: -16px 0 0 -16px;
    border: 2px solid;
    border-right-color: $(main.color);
    border-radius: 100%;
    animation: spinner 1.1s infinite linear;
    transform-origin: center
}

@-webkit-keyframes spinner {
    0 {
        -webkit-transform: rotate(0);
        transform: rotate(0)
    }
    to {
        -webkit-transform: rotate(1turn);
        transform: rotate(1turn)
    }
}

@keyframes spinner {
    0 {
        -webkit-transform: rotate(0);
        transform: rotate(0)
    }
    to {
        -webkit-transform: rotate(1turn);
        transform: rotate(1turn)
    }
}

.post-animated {
    -webkit-animation-duration: .5s;
    animation-duration: .5s;
    -webkit-animation-fill-mode: both;
    animation-fill-mode: both
}

@keyframes fadeIn {
    from {
        opacity: 0
    }
    to {
        opacity: 1
    }
}

.post-fadeIn {
    animation-name: fadeIn
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translate3d(0, 5px, 0)
    }
    to {
        opacity: 1;
        transform: translate3d(0, 0, 0)
    }
}

.post-fadeInUp {
    animation-name: fadeInUp
}

table {
    border-collapse: collapse;
    border-spacing: 0
}

.post-body tr {
    padding: 10px 0;
    font-size: 12px;
    line-height: 1.42
}

.post-body td.tr-caption {
    font-size: 11px;
    font-weight: 400;
    font-style: italic;
    font-stretch: normal;
    line-height: 1.42;
    padding: 10px 0;
    display: block;
    overflow: hidden;
    margin-bottom: 20px;
    letter-spacing: normal;
    color: #868686;
    border-bottom: 1px solid #eee
