    color: #1d9d74
}

.alert-message.error {
    background-color: #ffcdc7;
    border-color: #fdb1a8;
    color: $(main.color)
}

.alert-message.error a,
.alert-message.error span {
    color: #378fff
}

.alert-message.warning {
    background-color: $(footer.color) 4bb;
    border-color: #fc6;
    color: #e99b00
}

.alert-message.warning a,
.alert-message.warning span {
    color: #8a6d3b
}

.alert-message.alert {
    background-color: #bceeff;
    border-color: #8ae1ff;
    color: #21c2f8
}

.alert-message.alert a,
.alert-message.alert span {
    color: #f55d5d
}

.box-accordion {
    margin: 10px 0
}

.box-accordion>span {
    display: block;
    padding: 7px 15px;
    color: $(footer.color);
    font-weight: 600;
    cursor: pointer;
    background: $(title.color)
}

.box-accordion>span.active,
.box-accordion>span:hover {
    color: $(footer.color);
    background: $(main.color)
}

.box-accordion>div {
    background: #f1f1f1;
    padding: 20px
}

.box-tabs {
    margin: 0
}

.box-btn {
    overflow: auto
}

.box-btn span {
    padding: 8px 25px;
    background: #464646;
    font-size: 13px;
    display: block;
    font-weight: 600;
    color: $(footer.color);
    float: left;
    cursor: pointer
}

.box-btn span.active,
.box-btn span:hover {
    background: $(main.color);
    color: $(footer.color)
}

.box-tab-content {
    margin: 0 0 10px 0;
    padding: 20px;
    background-color: #f1f1f1
}

.post-body blockquote {
    margin: 25px 15px;
    padding: 0 20px;
    line-height: 26px;
    border-left: 5px solid $(main.color)
}

.widget .post-body li {
    line-height: 26px
}

ul.box-custom {
    list-style: none;
    list-style-type: none
}

ul.box-custom li:before {
    font-family: "remixicon";
    content: '\ea6e';
    padding-right: 10px;
    margin-left: -16px;
    line-height: 26px;
    font-size: 14px
}

ul.box-custom.box-arrow-li li:before {
    content: '\ea6e'
}

ul.box-custom.box-check-li li:before {
    content: '\f00c'
}

ul.box-custom.box-cross-li li:before {
    content: '\f00d'
}

ul.box-custom.box-multi li:before {
    display: none
}

ul.box-custom.box-multi li .fa {
    padding-right: 10px;
    margin-left: -16px;
    line-height: 26px;
    font-size: 14px
}

.box-colum {
    position: relative;
    overflow: hidden;
    display: flex
}

.box-f-colum3-two {
    padding: 0 25px
}

.box-f-colum {
    padding: 0 25px 0 0
}

.box-colum3-tree {
    padding-left: 25px
}

.box-f-colum4-one {
    padding-right: 12.5px
}

.box-colum4-tree,
.box-colum4-two {
    padding: 0 12.5px
}

.box-colum4-four {
    padding-left: 12.5px
}

#box-gallery {
    line-height: 0;
    -webkit-column-count: 3;
    -webkit-column-gap: 0;
    -moz-column-count: 3;
    -moz-column-gap: 0;
    column-count: 3;
    column-gap: 0
}

#box-gallery img {
    width: 100% !important;
    height: auto !important;
    padding: 2px
}

.type-dark {
    position: relative
}

.type-dark .switch {
    display: inline-block;
    position: relative;
    width: 45px;
    height: 25px;
    vertical-align: middle
}

.type-dark .switch input {
    opacity: 0;
    width: 0;
    height: 0
}

.type-dark input:checked+.slider1 {
    background-color: #333
}

.type-dark .slider1 {
    position: absolute;
    cursor: pointer;
    border-radius: 34px;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    -webkit-transition: .2s;
    transition: .2s
}

.type-dark .slider1 {
    background-color: rgba(0, 0, 0, .1)
}

.type-dark .slider1:before,
.type-dark .switch:hover .slider:before {
    background: $(posts.background.color)
}

.type-dark .slider1 {
    position: absolute;
    cursor: pointer;
    border-radius: 34px;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    -webkit-transition: .2s;
    transition: .2s
}

.type-dark .slider1:before {
    color: #666;
    background-color: $(posts.background.color);
    font-family: "remixicon";
    font-size: 14px;
    position: absolute;
    content: "\f1bc";
    height: 19px;
    line-height: 20px;
    width: 19px;
    text-align: center;
    left: 3px;
    border-radius: 50px;
    bottom: 3px;
    box-shadow: 0 1px 3px rgb(0 0 0 / 30%);
    transition: .25s
}

.type-dark input:checked+.slider1:before {
    content: "\ef72";
    -webkit-transform: translateX(19px);
    -ms-transform: translateX(19px);
    transform: translateX(19px);
    font-weight: 300
}

.lazyload,
.lazyloading {
    opacity: .3;
    -webkit-animation-duration: 1.25s;
    animation-duration: 1.25s;
    -webkit-animation-fill-mode: forwards;
    animation-fill-mode: forwards;
    -webkit-animation-iteration-count: infinite;
    animation-iteration-count: infinite;
    -webkit-animation-name: placeHolderShimmer;
    animation-name: placeHolderShimmer;
    -webkit-animation-timing-function: ease-in-out;
    animation-timing-function: ease-in-out;
    background: #d7dee0;
    background: -webkit-gradient(linear, left top, right top, color-stop(10%, #d7dee0), color-stop(18%, #c8cecf), color-stop(33%, #d7dee0));
    background: linear-gradient(to right, #d7dee0 10%, #c8cecf 18%, #d7dee0 33%);
    background-size: 200% 100% !important;
    -webkit-transition: opacity .2s ease-in-out;
    transition: opacity .2s ease-in-out
}

.lazyloaded {
    opacity: 1
}

@-webkit-keyframes placeHolderShimmer {
    0 {
        background-position: 100% 0
    }
    100% {
        background-position: -100% 0
    }
}

@keyframes placeHolderShimmer {
    0 {
        background-position: 100% 0
    }
    100% {
        background-position: -100% 0
    }
}

.btn-header .search-wrapper {
    margin: 0 0 0 30px;
    max-width: 400px;
    width: 100%
}

.search-wrapper .search-form {
    width: 100%;
    height: 40px;
    overflow: hidden;
    display: flex;
    border-radius: 30px;
    position: relative;
    padding: 0
}

.search-wrapper .search-input {
    width: 100%;
    height: 40px;
    color: $(title.color);
    margin: 0;
    padding: 0 20px;
    background-color: $(posts.background.color);
    font-size: 13px;
    font-weight: 400;
    font-family: inherit;
    box-shadow: -1px 2px 14px 0 rgb(0 0 0 / 18%) inset;
    line-height: 40px;
    outline: 0;
    box-sizing: border-box;
    border: 0
}

.search-wrapper .search-input:focus {
    box-shadow: -1px 2px 14px 0 rgba(0, 0, 0, .61) inset
}

.search-wrapper .search-submit {
    background-color: transparent;
    color: $(title.color);
    line-height: 40px;
    cursor: pointer;
    right: 15px;
    position: absolute;
    outline: 0;
    border: 0;
    transition: opacity .17s ease
}

.search-wrapper .search-submit:hover {
    opacity: .85
}

.search-wrapper ::placeholder {
    color: #777
}

a.more-link {
    font-size: 10px;
    color: #7b7b7b;
    font-weight: 500;
    float: right;
    position: relative;
    text-transform: uppercase
}

a.more-link:hover {
    color: $(main.color)
}

.btn-header {
    -ms-flex-order: 2;
    -webkit-box-flex: 1;
    -ms-flex: 1 1 auto;
    flex: 1 1 auto;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-pack: end;
    align-items: center;
    -ms-flex-pack: end;
    justify-content: flex-end
}

#toc {
    background: #f9f9f9;
    color: $(title.color);
    margin: 30px auto;
    padding: 20px;
    width: auto;
    border: 1px solid #eee;
    border-radius: 4px;
    overflow: hidden
}

#toc a {
    text-decoration: none;
    color: $(title.color)
}

#toc b.toc {
    text-transform: uppercase;
    font-size: 17px;
    padding: 5px 0 5px 10px
}

#toc ol {
    padding-left: 10px;
    margin: 0
}

#toc ol li {
    padding: 5px 0 0;
    font-size: 15px;
    color: $(title.color)
}

::marker {
    display: none
}

#toc ol li ol {
    overflow: hidden;
    margin: 0;
    padding: 0
}

#toc ol li ol li,
#toc>ol>ol li {
    list-style-type: disc
}

#toc>ol {
    counter-reset: item;
    list-style: none
}

#toc>ol li:before,
#toc>ol>li:before {
    content: counters(item, ".")" ";
    counter-increment: item;
    margin-right: 5px
}

#toc>ol>ol {
    overflow: hidden
}

.post-body h2[id]::before,
.post-body h3[id]::before {
    content: " ";
    margin-top: -72px;
    height: 72px;
    display: block;
    visibility: hidden
}

.toc button {
    float: right;
    border: 0;
    font-size: 18px;
    padding: 0;
    outline: 0;
    margin: 0;
    cursor: pointer;
    font-weight: 500;
    background-color: #f9f9f9
}

.darkmode,
.darkmode .header-wrapper {
    background: #222
}

.darkmode #footer,
.darkmode .menu-sticky.sticky {
    background: #212121
}

.darkmode .search-wrapper .search-input {
    color: $(footer.color);
    background-color: #3d3c3c
}

.darkmode .overlay.active {
    background: #000;
    opacity: .6
}

.darkmode,
.darkmode #main-menu ul>li>a,
.darkmode #myrelated h4,
.darkmode #relhead .darkmode .related-article ul li a,
.darkmode #relhead .related-article ul li a,
.darkmode #relhead span,
.darkmode #sidebar-wrapper .sidebar .post-title a,
.darkmode .Label ul li span,
.darkmode .Label ul li span:before,
.darkmode .author-description,
.darkmode .author-name span,
.darkmode .carousel-item .recent-title a,
.darkmode .cloud-label-widget-content a.label-name,
.darkmode .cloud-label-widget-content a.label-name:before,
.darkmode .comments,
.darkmode .comments .comments-content .comment-content,
.darkmode .comments .comments-content .comment-header a,
.darkmode .data-post h1.post-title,
.darkmode .footer-wrapper .footer h3,
.darkmode .mediapost .post-info>h2>a,
.darkmode .mobile-menu>ul>li>ul>li>a,
.darkmode .post-body h1,
.darkmode .post-body h2,
.darkmode .post-body h3,
.darkmode .post-body h4,
.darkmode .post-body h5,
.darkmode .post-body h6,
.darkmode .recent-wrap h3,
.darkmode .sidebar .Label li a,
.darkmode .sidebar .Label li a:before,
.darkmode .sidebar .widget-title>h3,
.darkmode .titlehome h3.home-title,
.darkmode .top-menu ul li a,
.darkmode a,
.darkmode .errorWrap,
.darkmode #relhead .related-article ol li a,
.darkmode h2.recent-title a {
    color: #eee
}

.darkmode .post-meta,
.darkmode .post-meta a,
.darkmode p.post-snippet {
    color: #a3a3a3
}

.darkmode #breadcrumb,
.darkmode #breadcrumb a,
.darkmode .search-wrapper .search-submit {
    color: #696969
}

.darkmode #main-menu ul>li>ul,
.darkmode #relhead,
.darkmode .Label ul li span,
.darkmode .about-author,
.darkmode .cloud-label-widget-content a.label-name,
.darkmode .comments .comments-content .comment-content,
.darkmode .post-labels a,
.darkmode .post-labels span,
.darkmode .sidebar .Label li a {
    background: #333
}

.darkmode .data-post .post-body {
    border-top: 2px dotted #313131
}

.darkmode .mobile-menu ul li {
    border-bottom: 1px solid #373636
}

.darkmode #relhead .related-article ul li {
    border-right: 1px solid #434343
}

.darkmode .mobile-menu ul li.has-sub .submenu-toggle:after {
    border: 1px solid #373636
}

.darkmode .box-accordion>div,
.darkmode .box-tab-content {
    background-color: #313131
}

.darkmode .box-accordion>span {
    background: #3b3b3b
}

.darkmode .mobile-menu .menu .menu-social .menu-social1 {
    background: #292929
}

.darkmode .menu .menu-social .menu-social1 {
    background: 0
}

@media screen and (max-width:1024px) {
    .container {
        max-width: 98%
    }
    .featured li:nth-child(2) {
        height: 352px
    }
    .featured li:nth-child(4) {
        margin-top: 8px
    }
}

@media screen and (max-width:980px) {
    .header-wrapper {
        padding: 0;
        position: sticky;
        top: 0;
        z-index: 999
    }
    #jt_header {
        padding: 0
    }
    .menu-wrapper .progress {
        display: none !important
    }
    .header-wrapper .progress {
        display: block
    }
    .darkmode .menu {
        -webkit-box-shadow: 8px 0 14px -7px rgb(29 28 28);
        -moz-box-shadow: 8px 0 14px -7px rgb(29 28 28);
        box-shadow: 8px 0 14px -7px rgb(29 28 28);
        background: #222
    }
    .menu .mobile-box {
        display: flex;
        -flex-flow: row wrap;
        flex-flow: row wrap;
        overflow: hidden;
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 20px;
        box-shadow: 0 2px 10px 1px rgb(0 0 0 / 8%)
    }
    .menu .mobile-box .search-mobile {
        flex: 1
    }
    .menu-sticky {
        top: 0
    }
    .menu-sticky.sticky {
        position: relative !important;
        top: 0 !important;
        box-shadow: none !important;
        left: initial !important
    }
    #main-menu,
    .header-menu {
        height: auto
    }
    .btn-header,
    .btn-header .search-wrapper,
    .menu .jetbtn,
    .menu .type-dark,
    .top-menu {
        display: none !important
    }
    #jt_header .jetbtn,
    .jetbtn,
    .menu-sticky .jetbtn,
    .menu-sticky .type-dark {
        display: block
    }
    .featured li:nth-child(2) {
        height: 338px
    }
}

@media screen and (max-width:880px) {
    #sidebar-wrapper {
        margin-top: 50px
    }
    .featured li:first-child {
        width: 50%;
        padding-right: 5px
    }
    .featured .rcp-title a {
        display: -webkit-box;
        overflow: hidden;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical
    }
    .featured li:first-child h2.rcp-title {
        font-size: 18px
    }
    .featured li:nth-child(2) {
        height: auto;
        width: 50%;
        padding-right: 5px
    }
    .featured li {
        width: 50%;
        padding: 5px
    }
    .featured li:nth-child(4) {
        margin-top: 0
    }
    #main-wrapper,
    #sidebar-wrapper {
        -ms-flex: 1 1 100%;
        flex: 1 1 100%;
        max-width: 100%
    }
    .post-snippet,
    .recentlist .recent-content p {
        position: absolute;
        text-indent: -9999999px
    }
    #sidebar-wrapper .sidebar,
    #sidebar-wrapper.widget {
        position: relative;
        top: initial;
        padding-left: 0
    }
}

@media screen and (max-width:800px) {
    .item #main-wrapper,
    .item #sidebar-wrapper {
        -webkit-box-flex: 1;
        -ms-flex: 1 1 100%;
        flex: 1 1 100%;
        max-width: 100%;
        min-width: 0;
        padding-right: 0
    }
}

@media screen and (max-width:768px) {
    #main-wrapper,
    #sidebar-wrapper {
        -ms-flex: 1 1 100%;
        flex: 1 1 100%;
        max-width: 100%;
        min-width: 0;
        padding-right: 0
    }
    #relhead .related-article ol {
        grid-template-columns: repeat(1, minmax(0, 1fr));
        gap: 0.3rem;
    }
    #sidebar-wrapper .section,
    #sidebar-wrapper.widget {
        position: relative;
        top: auto
    }
    .recent404-wrapper .recent404 ul {
        grid-template-columns: repeat(2, minmax(0, 1fr))
    }
}

@media screen and (max-width:560px) {
    .featured .post-panel {
        left: 20px;
        right: 20px;
        bottom: 10px
    }
    .featured h2.rcp-title,
    .featured li:first-child h2.rcp-title {
        font-size: 15px
    }
    .gridmode .mediapost {
        width: 50%
    }
    .popup-container {
        max-width: 80%
    }
    .errorWrap h3 {
        font-size: 84px;
        line-height: 1;
        margin: 0 0 20px
    }
    .rcimg {
        width: 200px;
        margin-right: 20px
    }
    .mediapost .post-info>h2,
    .recent-content h2 {
        font-size: 20px
    }
    .popup-container input.search-input {
        padding: 5px 25px;
        height: 40px;
        font-size: 13px
    }
    .popup-container button.search-submit {
        top: 13px
    }
    .about-author {
        display: block;
        margin: 0 0 30px
    }
    .aboutimg {
        display: block;
        -ms-flex: 1 1 100%;
        flex: 1 1 100%;
        max-width: 100%
    }
    .about-wrapper {
        display: block;
        -ms-flex: 1 1 100%;
        flex: 1 1 100%;
        max-width: 100%;
        text-align: center
    }
    .about-author .avatar-container {
        float: none;
        margin: 0 auto 15px
    }
    #relhead .related-article ul {
        display: block
    }
    #relhead .related-article ul li {
        padding: 7px 10px;
        border-right: 0
    }
}

@media screen and (max-width:515px) {
    .rcimg {
        width: 150px
    }
    .carousel-item .recent-title a,
    .mediapost .post-info>h2>a {
        display: -webkit-box;
        overflow: hidden;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical
    }
    .mediapost .post-info>h2,
    .recent-content h2 {
        font-size: 18px
    }
}

@media screen and (max-width:480px) {
    .featured li {
        width: 100%;
        padding: 5px
    }
    .featured li:first-child {
        width: 100%;
        padding-right: 0
    }
    .featured li:nth-child(2) {
        height: auto;
        width: 100%;
        padding-right: 0
    }
    .featured .post-panel {
        left: 30px;
        right: 30px;
        bottom: 30px
    }
    .featured h2.rcp-title,
    .featured li:first-child h2.rcp-title {
        font-size: 17px
    }
}

@media screen and (max-width:440px) {
    .related-wrap li {
        flex: 1 1 50%;
        max-width: 50%
    }
    .mediapost .post-info>h2,
    .recent-content h2 {
        font-size: 17px
    }
    .post-labels a,
    .post-labels span {
        margin: 0 5px 10px !important
    }
    .about-author .avatar-container {
        float: none;
        margin: 0 auto 10px
    }
    .about-author {
        text-align: center
    }
    .container {
        max-width: 100%
    }
}

@media screen and (max-width:384px) {
    .header-logo img {
        height: 28px;
        margin-top: 5px
    }
    .rcimg {
        width: 110px
    }
    .recent404-wrapper .recent404 ul {
        grid-template-columns: repeat(1, minmax(0, 1fr))
    }
}

@media screen and (max-width:320px) {
    .rcimg {
        width: 100%;
        margin-right: 0;
        margin-bottom: 10px
    }
}

