$("#gsrelated").each(function() {
    var e = $(this).text();
    $.ajax({
        url: "/feeds/posts/default/-/" + e + "?alt=json-in-script&max-results=5",
        type: "get",
        dataType: "jsonp",
        success: function(e) {
            for (var t = "", a = "<ul>", r = 0; r < e.feed.entry.length; r++) {

                for (var s = 0; s < e.feed.entry[r].link.length; s++) {
                    if ("alternate" == e.feed.entry[r].link[s].rel) {
                        t = e.feed.entry[r].link[s].href;
                        break;
                    }
                }

                var n = e.feed.entry[r].title.$t,
                    c = e.feed.entry[r].author[0].name.$t,
                    l = e.feed.entry[r].category[0].term,
                    i = e.feed.entry[r].published.$t,
                    d = i.substring(0, 4), // tahun
                    f = i.substring(5, 7), // bulan
                    p = i.substring(8, 10); // tanggal

                // ✅ FORMAT BARU
                var o = p + " " + month_format[parseInt(f, 10)] + " " + d;

                var u = e.feed.entry[r].content.$t,
                    g = $("<div>").html(u);

                var desc = "";
                if ("content" in e.feed.entry[r]) {
                    desc = e.feed.entry[r].content.$t;
                } else if ("summary" in e.feed.entry[r]) {
                    desc = e.feed.entry[r].summary.$t;
                }

                var regex = /<\S[^>]*>/g;
                desc = desc.replace(regex, "");
                if (desc.length > 120) {
                    desc = desc.substring(0, 120) + "...";
                }

                var m;
                if (u.indexOf("//www.youtube.com/embed/") > -1) {
                    m = e.feed.entry[r].media$thumbnail.url.replace("/default.jpg", "/maxresdefault.jpg");
                } else if (u.indexOf("<img") > -1) {
                    m = g.find("img:first").attr("src").replace("s72-c", "s1600");
                } else {
                    m = no_image;
                }

                a += '<li><div class="rcimg"><div class="rec-image"><a href="' + t + '" title="' + n + '"><img class="lazyload" data-sizes="auto" alt="' + n + '" data-src="' + m + '" src="' + imglazy + '" width="' + widthZise + '" height="' + heightZise + '"/></a></div></div>';

                a += '<div class="recent-content">';
                a += '<h2 class="recent-title"><a href="' + t + '" title="' + n + '">' + n + '</a></h2>';
                a += '<div class="post-meta">';
                a += '<span class="post-author">' + c + '</span>';
                a += '<span class="post-tag"><a href="/search/label/' + l + '?&max-results=6">' + l + '</a></span>';
                a += '<span class="recent-date">' + o + '</span>';
                a += '</div>';
                a += '<p class="post-snippet">' + desc + '</p>';
                a += '</div></li>';
            }

            a += "</ul>";
            $("#gsrelated").html(a);

            $(".lazyload").each(function() {
                $(this).attr("data-src", function(e, t) {
                    return t.replace("/default.jpg", "/maxresdefault.jpg");
                }).attr("data-src", function(e, t) {
                    return t.replace("s72-c", "s1600");
                });
            });
        }
    });
});

